from collections import defaultdict

def get_components_and_sizes(grid):
    """Returns dict: color -> list of (component_cells, is_single_cell_containing)"""
    visited = set()
    result = defaultdict(list)

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 9 and (r, c) not in visited:
                color = grid[r][c]
                component = []
                stack = [(r, c)]
                while stack:
                    rr, cc = stack.pop()
                    if (rr, cc) in visited:
                        continue
                    visited.add((rr, cc))
                    component.append((rr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                stack.append((nr, nc))

                # Check if this component has any single-cell neighbors
                has_single_neighbor = False
                for cr, cc in component:
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
                            nval = grid[nr][nc]
                            # Is (nr, nc) a single cell of the same color?
                            if nval == color:
                                # Check if it's single
                                neighbors_of_neighbor = []
                                for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
                                    nnr, nnc = nr + ddr, nc + ddc
                                    if 0 <= nnr < len(grid) and 0 <= nnc < len(grid[nnr]):
                                        neighbors_of_neighbor.append((nnr, nnc, grid[nnr][nnc]))
                                if all(n[2] != color for n in neighbors_of_neighbor):
                                    has_single_neighbor = True

                result[color].append((list(component), has_single_neighbor))

    return result

